	rawLog, _, rawErr := checkpoint.ResolveRawSessionLogForCheckpoint(ctx, fullCheckpointID, v1Store, v2Store, preferCheckpointsV2)
	if rawErr != nil {
		return fmt.Errorf("failed to read raw transcript: %w", rawErr)

